// ─────────────────────────────────────────────────────────────────────────
//  01 · derived query parser★★★
//  concepts: Spring Data naming · regex · records
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.regex.*;

class Exercise {

    enum Op { EQUALS, GREATER_THAN, LESS_THAN, CONTAINING, IS_NULL }
    record Condition(String property, Op op) {}
    record Sort(String property, boolean descending) {}
    record QuerySpec(String action, List<Condition> conditions, List<Sort> orderBy) {}

    static final Pattern SHAPE = Pattern.compile("^(find|count|exists|delete)\\w*?By(.+?)(?:OrderBy(.+))?$");
    static final Map<String, Op> SUFFIXES = new LinkedHashMap<>(Map.of(
        "GreaterThan", Op.GREATER_THAN, "LessThan", Op.LESS_THAN, "Containing", Op.CONTAINING, "IsNull", Op.IS_NULL));

    /** A small derived-query grammar: action, And-joined conditions, optional OrderBy. */
    static QuerySpec parse(String method) {
        if (method == null) throw new IllegalArgumentException("method name is required");
        Matcher m = SHAPE.matcher(method);
        if (!m.matches()) throw new IllegalArgumentException("unsupported method name: " + method);
        if (m.group(2).contains("Or")) throw new IllegalArgumentException("Or is not supported: " + method);
        var conditions = new ArrayList<Condition>();
        for (var part : m.group(2).split("And", -1)) conditions.add(condition(part));
        var orderBy = new ArrayList<Sort>();
        if (m.group(3) != null) {
            for (var part : m.group(3).split("(?<=Asc|Desc)")) {
                boolean desc = part.endsWith("Desc");
                String prop = part.endsWith("Desc") ? part.substring(0, part.length() - 4) : part.endsWith("Asc") ? part.substring(0, part.length() - 3) : part;
                orderBy.add(new Sort(property(prop), desc));
            }
        }
        return new QuerySpec(m.group(1), conditions, orderBy);
    }

    static Condition condition(String part) {
        for (var e : SUFFIXES.entrySet()) {
            if (part.endsWith(e.getKey())) return new Condition(property(part.substring(0, part.length() - e.getKey().length())), e.getValue());
        }
        return new Condition(property(part), Op.EQUALS);
    }

    static String property(String raw) {
        if (raw.isEmpty()) throw new IllegalArgumentException("empty property name");
        return Character.toLowerCase(raw.charAt(0)) + raw.substring(1);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("conditions and ordering", () -> eq(parse("findByStatusAndTotalGreaterThanOrderByCreatedAtDesc"), new QuerySpec("find", List.of(new Condition("status", Op.EQUALS), new Condition("total", Op.GREATER_THAN)), List.of(new Sort("createdAt", true)))));
        test("count and exists actions", () -> eq(List.of(parse("countByStatus").action(), parse("existsByCustomerEmail").action()), List.of("count", "exists")));
        test("subject words before By are ignored", () -> eq(parse("findTop10ByNameContaining").conditions(), List.of(new Condition("name", Op.CONTAINING))));
        test("a property without a direction sorts ascending", () -> eq(parse("findByShippedAtIsNullOrderByName"), new QuerySpec("find", List.of(new Condition("shippedAt", Op.IS_NULL)), List.of(new Sort("name", false)))));
        test("explicit Asc and Desc keys", () -> eq(parse("findByStatusOrderByStatusAscCreatedAtDesc").orderBy(), List.of(new Sort("status", false), new Sort("createdAt", true))));
        test("unsupported names are rejected (boundary)", () -> { for (var bad : new String[] { "findAll", "getByStatus", "findByStatusOrName", "findByStatusAnd", "findBy" }) raises(IllegalArgumentException.class, () -> parse(bad)); });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

