import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    static class Order {
        private Long id;              // @Id @GeneratedValue: null until persist assigns it
        private String status;

        Order(String status) { this.status = status; }

        Long getId() { return id; }
        String getStatus() { return status; }
        /** what persist does with a generated id */
        void assignId(long id) { this.id = id; }

        /** Same instance, or both ids assigned and equal; a new (id-less) entity equals only itself. */
        @Override
        public boolean equals(Object o) {
            throw new UnsupportedOperationException("TODO: identity, then compare ids read through getId(); null ids never match");
        }

        /** Must not change when the id is assigned. */
        @Override
        public int hashCode() {
            throw new UnsupportedOperationException("TODO: a value that is the same before and after persist");
        }
    }

    /** What Hibernate hands out for a lazy reference: a subclass whose own fields stay empty and whose getters delegate. */
    static class OrderProxy extends Order {
        private final Order target;
        OrderProxy(Order target) { super(null); this.target = target; }
        @Override Long getId() { return target.getId(); }
        @Override String getStatus() { return target.getStatus(); }
    }

    static Order persisted(long id) {
        var o = new Order("placed");
        o.assignId(id);
        return o;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("an entity added to a set before persist is still found after its id is assigned", () -> {
            var o = new Order("new");
            var set = new HashSet<Order>();
            set.add(o);
            o.assignId(42);
            ok(set.contains(o), "the set lost the entity when its id was assigned");
        });
        test("two new entities are different, even with equal fields (boundary)", () -> {
            var a = new Order("new");
            var b = new Order("new");
            ok(!a.equals(b) && !b.equals(a), "two unsaved entities compared equal");
            eq(new HashSet<>(List.of(a, b)).size(), 2);
        });
        test("two loaded copies of the same row are equal", () -> ok(persisted(7).equals(persisted(7)), "same id, different instances must be equal"));
        test("different ids are different entities", () -> ok(!persisted(7).equals(persisted(8)), "ids 7 and 8 compared equal"));
        test("a lazy proxy equals its entity, both ways, and is found in a set holding it", () -> {
            var o = persisted(7);
            var proxy = new OrderProxy(persisted(7));
            ok(o.equals(proxy) && proxy.equals(o), "an entity and its proxy must be equal");
            ok(new HashSet<>(List.of(o)).contains(proxy), "the set did not find the proxy");
        });
        test("equals is reflexive and rejects null and other types", () -> {
            var o = new Order("new");
            ok(o.equals(o), "a new entity must equal itself");
            ok(!persisted(7).equals(null) && !persisted(7).equals(7L), "an entity equalled null or a Long");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

