    /** One persistence context over an orders table (id -> status). */
    static class Session {
        final Map<Long, String> table;
        final Map<Long, Order> managed = new HashMap<>();   // the first-level cache: one instance per id
        long nextId;
        int selects;

        Session(Map<Long, String> table, long nextId) { this.table = table; this.nextId = nextId; }

        /** Given: dirty checking at flush writes the state of every MANAGED instance. */
        void flush() { for (var o : managed.values()) table.put(o.id, o.status); }

        /** The managed instance for id: the persistence context first, else one SELECT; null when the row is missing. */
        Order find(long id) {
            throw new UnsupportedOperationException("TODO: managed instance first, else select, manage and return");
        }

        /** SimpleJpaRepository.save: persist a new entity, merge an existing one. */
        Order save(Order entity) {
            throw new UnsupportedOperationException("TODO: id null -> persist (manage THIS instance); else merge (copy onto the managed one)");
        }
    }

    static Session session() { return new Session(new HashMap<>(Map.of(1L, "placed")), 100); }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("saving a new entity persists that very instance", () -> {
            var s = session();
            var o = new Order(null, "new");
            ok(s.save(o) == o, "persist must manage and return the same object");
            s.flush();
            eq(List.of(o.id, s.table.get(100L)), List.of(100L, "new"));
        });
        test("saving a detached entity returns a different, managed instance with its state", () -> {
            var s = session();
            var detached = new Order(1L, "paid");
            var managed = s.save(detached);
            ok(managed != detached, "merge must not return its argument");
            eq(managed.status, "paid");
        });
        test("after a merge, edits to the argument are lost and edits to the result are saved", () -> {
            var s = session();
            var detached = new Order(1L, "paid");
            var managed = s.save(detached);
            detached.status = "cancelled";
            s.flush();
            eq(s.table.get(1L), "paid");
            managed.status = "shipped";
            s.flush();
            eq(s.table.get(1L), "shipped");
        });
        test("find returns one instance per id with one select", () -> {
            var s = session();
            var a = s.find(1L);
            ok(a == s.find(1L), "find created a second instance");
            eq(s.selects, 1);
        });
        test("merging onto an instance that is already managed needs no select (boundary)", () -> {
            var s = session();
            var managed = s.find(1L);
            var result = s.save(new Order(1L, "paid"));
            ok(result == managed, "merge must copy onto the managed instance");
            eq(List.of(managed.status, s.selects), List.of("paid", 1));
        });
        test("saving the managed instance itself returns it", () -> {
            var s = session();
            var managed = s.find(1L);
            managed.status = "packed";
            ok(s.save(managed) == managed, "save of a managed entity must return it");
            s.flush();
            eq(s.table.get(1L), "packed");
        });
        test("find of a missing id is null", () -> eq(session().find(9L), null));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

