// ─────────────────────────────────────────────────────────────────────────
//  03 · save is persist or merge★★★
//  concepts: persistence context · persist keeps the instance · merge returns a copy
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    static class Order {
        Long id;
        String status;
        Order(Long id, String status) { this.id = id; this.status = status; }
    }

    /** One persistence context over an orders table (id -> status). */
    static class Session {
        final Map<Long, String> table;
        final Map<Long, Order> managed = new HashMap<>();   // the first-level cache: one instance per id
        long nextId;
        int selects;

        Session(Map<Long, String> table, long nextId) { this.table = table; this.nextId = nextId; }

        /** Given: dirty checking at flush writes the state of every MANAGED instance. */
        void flush() { for (var o : managed.values()) table.put(o.id, o.status); }

        /** The managed instance for id: the persistence context first, else one SELECT; null when the row is missing. */
        Order find(long id) {
            var known = managed.get(id);
            if (known != null) return known;
            selects++;
            String status = table.get(id);
            if (status == null) return null;
            var loaded = new Order(id, status);
            managed.put(id, loaded);
            return loaded;
        }

        /** SimpleJpaRepository.save: persist a new entity, merge an existing one. */
        Order save(Order entity) {
            if (entity.id == null) {              // isNew: persist
                entity.id = nextId++;
                managed.put(entity.id, entity);
                return entity;
            }
            var target = find(entity.id);         // merge: the managed instance for that id
            if (target != entity) target.status = entity.status;
            return target;                        // the argument stays detached
        }
    }

    static Session session() { return new Session(new HashMap<>(Map.of(1L, "placed")), 100); }

    // ─── tests ───────────────────────────────────────────────────────────
